function DatabaseSync(filename, options) {
  let SQLiteDatabaseSync;
  try {
    ({ DatabaseSync: SQLiteDatabaseSync } = require('node:sqlite'));
  } catch (cause) {
    if (cause?.code !== 'ERR_UNKNOWN_BUILTIN_MODULE' && cause?.code !== 'MODULE_NOT_FOUND') throw cause;
    const error = new Error('Multiple CRM local backup/restore needs Node.js 24.19.0 or newer. In Render > Environment set NODE_VERSION=24.19.0, save and redeploy.');
    error.code = 'NODE_SQLITE_UNAVAILABLE';
    error.status = 503;
    error.cause = cause;
    throw error;
  }
  if (typeof SQLiteDatabaseSync !== 'function') {
    const error = new Error('node:sqlite DatabaseSync is unavailable. Use Node.js 24.19.0 or newer.');
    error.code = 'NODE_SQLITE_UNAVAILABLE';
    error.status = 503;
    throw error;
  }
  return new SQLiteDatabaseSync(filename, options);
}
