function policyHash(s){return sha(canonical({version:'CC874-portable-v2',key_policy:s.settings?.key_policy||{}}));}
function compatibleBase(meta,s){return !!meta&&meta.source_instance===s.instance_uuid&&meta.head.dataset_uuid===s.dataset_uuid&&meta.head.branch_uuid===s.branch_uuid&&BigInt(meta.head.revision)<=BigInt(s.revision)&&meta.policy_hash===policyHash(s)&&meta.signing_public_key===s.signing_public_key;}
